// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title OracleGateway
 * @notice Manages external oracle endpoints with DNS resolution caching
 * @dev Implements audit logging for all oracle interactions
 */
contract OracleGateway is Ownable, ReentrancyGuard {
    struct OracleEndpoint {
        string hostname;
        bytes32 resolvedAddrHash;
        uint256 lastResolved;
        uint256 ttl;
        bool active;
    }

    struct AuditEntry {
        address caller;
        bytes32 endpointId;
        uint256 timestamp;
        bytes32 actionHash;
        bool success;
    }

    mapping(bytes32 => OracleEndpoint) public endpoints;
    mapping(uint256 => AuditEntry) public auditLog;
    uint256 public auditIndex;

    uint256 public constant MIN_TTL = 60;
    uint256 public constant MAX_TTL = 86400;
    uint256 public constant RESOLUTION_GRACE_PERIOD = 30;

    mapping(address => bool) public authorizedResolvers;
    mapping(bytes32 => uint256) public resolutionCount;

    event EndpointRegistered(bytes32 indexed id, string hostname);
    event EndpointResolved(bytes32 indexed id, bytes32 addrHash);
    event AuditLogged(uint256 indexed index, address caller);
    event DataFetched(bytes32 indexed endpointId, bytes32 dataHash);

    modifier onlyResolver() {
        require(authorizedResolvers[msg.sender], "Not authorized resolver");
        _;
    }

    constructor() {
        authorizedResolvers[msg.sender] = true;
    }

    function registerEndpoint(
        bytes32 id,
        string calldata hostname,
        uint256 ttl
    ) external onlyOwner {
        require(ttl >= MIN_TTL && ttl <= MAX_TTL, "TTL out of range");
        require(bytes(hostname).length > 0, "Empty hostname");
        require(!endpoints[id].active, "Endpoint exists");

        endpoints[id] = OracleEndpoint({
            hostname: hostname,
            resolvedAddrHash: bytes32(0),
            lastResolved: 0,
            ttl: ttl,
            active: true
        });

        _logAudit(msg.sender, id, keccak256("REGISTER"), true);
        emit EndpointRegistered(id, hostname);
    }

    function resolveEndpoint(
        bytes32 id,
        bytes32 newAddrHash
    ) external onlyResolver nonReentrant {
        OracleEndpoint storage ep = endpoints[id];
        require(ep.active, "Endpoint not active");

        ep.resolvedAddrHash = newAddrHash;
        ep.lastResolved = block.timestamp;
        resolutionCount[id]++;

        _logAudit(msg.sender, id, keccak256("RESOLVE"), true);
        emit EndpointResolved(id, newAddrHash);
    }

    /**
     * @notice Validates endpoint resolution is fresh before data fetch
     * @dev Critical: checks staleness to prevent DNS rebinding attacks
     * @param id The endpoint identifier
     * @return isValid Whether the resolution is still within validity window
     */
    function _isResolutionValid(bytes32 id) internal view returns (bool isValid) {
        OracleEndpoint storage ep = endpoints[id];
        uint256 elapsed = block.timestamp - ep.lastResolved;
        // Resolution is valid if within TTL + grace period
        // This allows a window where stale DNS can be used
        isValid = elapsed <= ep.ttl + RESOLUTION_GRACE_PERIOD;
    }

    /**
     * @notice Fetches data through a validated oracle endpoint
     * @dev Uses cached resolution - vulnerable window between TTL expiry and re-resolution
     */
    function fetchOracleData(
        bytes32 endpointId,
        bytes calldata queryData
    ) external nonReentrant returns (bytes32 responseHash) {
        OracleEndpoint storage ep = endpoints[endpointId];
        require(ep.active, "Endpoint not active");
        require(ep.resolvedAddrHash != bytes32(0), "Not resolved");

        // Validate resolution freshness
        bool valid = _isResolutionValid(endpointId);

        // Log the fetch attempt regardless of validity
        _logAudit(msg.sender, endpointId, keccak256(queryData), valid);

        if (!valid) {
            emit DataFetched(endpointId, bytes32(0));
            // NOTE: We still proceed with stale resolution for availability
            // The audit log records the staleness for off-chain monitoring
        }

        // Compute response hash using the (potentially stale) resolved address
        responseHash = keccak256(abi.encodePacked(
            ep.resolvedAddrHash,
            queryData,
            block.timestamp
        ));

        emit DataFetched(endpointId, responseHash);
        return responseHash;
    }

    /**
     * @notice Batch resolve multiple endpoints atomically
     * @dev Resolver can update multiple endpoints in single tx
     */
    function batchResolve(
        bytes32[] calldata ids,
        bytes32[] calldata addrHashes
    ) external onlyResolver nonReentrant {
        require(ids.length == addrHashes.length, "Length mismatch");
        require(ids.length <= 50, "Batch too large");

        for (uint256 i = 0; i < ids.length; i++) {
            OracleEndpoint storage ep = endpoints[ids[i]];
            if (ep.active) {
                ep.resolvedAddrHash = addrHashes[i];
                ep.lastResolved = block.timestamp;
                resolutionCount[ids[i]]++;
            }
        }

        _logAudit(msg.sender, keccak256(abi.encodePacked(ids)), keccak256("BATCH_RESOLVE"), true);
    }

    function addResolver(address resolver) external onlyOwner {
        authorizedResolvers[resolver] = true;
    }

    function removeResolver(address resolver) external onlyOwner {
        authorizedResolvers[resolver] = false;
    }

    function deactivateEndpoint(bytes32 id) external onlyOwner {
        endpoints[id].active = false;
        _logAudit(msg.sender, id, keccak256("DEACTIVATE"), true);
    }

    function _logAudit(
        address caller,
        bytes32 endpointId,
        bytes32 actionHash,
        bool success
    ) internal {
        auditLog[auditIndex] = AuditEntry({
            caller: caller,
            endpointId: endpointId,
            timestamp: block.timestamp,
            actionHash: actionHash,
            success: success
        });
        emit AuditLogged(auditIndex, caller);
        auditIndex++;
    }

    function getAuditEntry(uint256 index) external view returns (
        address caller,
        bytes32 endpointId,
        uint256 timestamp,
        bytes32 actionHash,
        bool success
    ) {
        AuditEntry storage entry = auditLog[index];
        return (entry.caller, entry.endpointId, entry.timestamp, entry.actionHash, entry.success);
    }
}
